#!/usr/bin/env bash
# generated-touch.sh: SW-CORE-05, generated Swift files a change edits. Generated code is regenerated from its spec,
# never edited by hand.
# Usage: BASE=origin/main bash generated-touch.sh      (run from the repository root; BASE = the merge target)
# A file is generated by path (*.pb.swift, *.grpc.swift, *.generated.swift, *+Generated.swift, a Generated/ or
# generated/ directory) or by a marker line in its first 40 lines that starts at column 0 with // and says
# DO NOT EDIT, automatically generated, AUTO-GENERATED or Generated file|by|using. An indented marker is template text.
# Output is the violation: "file: path" or "file: marker line N". Every line needs "regenerated by COMMAND" in the PR.
# Exit: 0 and no output = no generated file touched; 1 = at least one printed; 64 BASE unset; 66 BASE does not resolve.
# Stages *.swift (`git add`), which changes the index and no file. Needs git 2.30 or newer for --merge-base.
# Watched red (4 files) and green (0) on a planted change (measured 2026-10-10).
set -u
[ -n "${BASE:-}" ] || { echo 'generated-touch: set BASE to the merge target, for example origin/main' >&2; exit 64; }
git rev-parse --verify --quiet "${BASE}^{commit}" > /dev/null || { echo "generated-touch: BASE does not resolve: $BASE" >&2; exit 66; }
git add -A -- '*.swift'
list=$(mktemp)
out=$(mktemp)
trap 'rm -f "$list" "$out"' EXIT
git diff --name-only -z --diff-filter=d --merge-base "$BASE" -- '*.swift' > "$list" || { echo 'generated-touch: git diff failed' >&2; exit 66; }
# shellcheck disable=SC2016  # the awk program is single-quoted on purpose
xargs -r -0 awk '
  FNR == 1 && FILENAME ~ /(\.pb|\.grpc|\.generated)\.swift$|\+Generated\.swift$|(^|\/)[Gg]enerated\// && !seen[FILENAME]++ { print FILENAME ": path" }
  FNR <= 40 && $0 ~ /^\/\/([^\/]|$).*([Dd][Oo] [Nn][Oo][Tt] [Ee][Dd][Ii][Tt]|[Aa]utomatically [Gg]enerated|AUTO-GENERATED|[Gg]enerated (file|by|using))/ && !seen[FILENAME]++ { print FILENAME ": marker line " FNR }' < "$list" > "$out"
cat "$out"
[ ! -s "$out" ]
